from __future__ import absolute_import, division, print_function,\
    unicode_literals
# from SSHLibrary import SSHClient, abstractclient
from builtins import object
from future import standard_library
import os
import time
import subprocess
import sys
from shutil import move
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf_exceptions import IperfExecutionError
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf_exceptions import ProcessIsAlreadyRunning
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf_exceptions import StartProcessError
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()
standard_library.install_aliases()


class IperfProcess(object):

    def __init__(self, iperf_pc_ssh_client, ue_pc_ssh_client):
        self._iperf_pc_ssh = iperf_pc_ssh_client
        self._ue_pc_ssh = ue_pc_ssh_client
        self._pid = None
        self._adb_pid = None
        self._cmd = None
        self._adb_cmd = None

    @property
    def pid(self):
        """ Get process id.

        :return:        Shell process id.
        :rtype:         string
        """
        return self._pid

    @pid.setter
    def pid(self, pid):
        """ Set process id.

        :param string pid:      Shell process id.
        """
        if self._pid is not None:
            raise ProcessIsAlreadyRunning("{} process is running".format(
                self.__class__.__name__))
        self._pid = pid

    @property
    def adb_pid(self):
        """ Get process id.

        :return:        Shell process id.
        :rtype:         string
        """
        return self._adb_pid

    @adb_pid.setter
    def adb_pid(self, adb_pid):
        """ Set process id.

        :param string pid:      Shell process id.
        """
        if self._adb_pid is not None:
            raise ProcessIsAlreadyRunning("{} process is running".format(
                self.__class__.__name__))
        self._adb_pid = adb_pid

    def start_process_ue_pc(self, cmd, log_file):
        self._adb_cmd = cmd
        self._ue_log = log_file
        logger.debug("UE log: {}".format(self._ue_log))
        self.adb_pid = self.start_process(cmd, self._ue_pc_ssh)
        logger.debug("Adb iperf process id : {}".format(self.adb_pid))

    def start_process_iperf_pc(self, cmd, log_file):
        self._remote_log = log_file
        self.pid = self.start_process(cmd, self._iperf_pc_ssh)
        logger.debug("iperf pc process id : {}".format(self.pid))

    def start_process(self, cmd, ssh):
        pid = self._execute(cmd, ssh)
        self._is_process_started(pid, cmd, ssh)
        return pid

    def stop_process_ue_pc(self, signal='9'):
        self.stop_process(self.adb_pid, self._adb_cmd, self._ue_pc_ssh, signal)

    def stop_process_iperf_pc(self, signal='9'):
        self.stop_process(self.pid, self._cmd, self._iperf_pc_ssh, signal)

    def stop_process(self, pid, cmd, ssh, signal='9',):
        killcmd = 'kill -{} {} || true'.format(signal, pid)
        self._execute(killcmd, ssh)
        self._is_process_stopped(pid, cmd, ssh)

    def get_log_files(self):
        return self.get_ue_pc_log_file(), self.get_iperf_pc_log_file()

    def get_ue_pc_log_file(self):
        return self.get_log_file(self._ue_log, self._ue_pc_ssh)

    def get_iperf_pc_log_file(self):
        return self.get_log_file(self._remote_log, self._iperf_pc_ssh)

    def get_log_file(self, logfile, ssh):
        dest = 'execution_logs/{}'.format(logfile)
        logger.debug("Destination filename for ue log file: {}".format(dest))
        if not os.path.exists(os.path.dirname(dest)):
            os.makedirs(os.path.dirname(dest))
        if ssh is None:
            move(logfile, dest)
        else:
            ssh.get_file(logfile, 'execution_logs/')
            ssh.execute_command('rm -f ' + self._remote_log)
        return dest

    def execute(self, cmd, ssh):
        self._execute(cmd, ssh)

    def _execute(self, cmd, ssh):
        if ssh is None:
            try:
                out = subprocess.check_output(cmd, shell=True)
                out = out.strip()
            except subprocess.CalledProcessError:
                raise IperfExecutionError()
            else:
                return out
        else:
            logger.info('cmd: {}'.format(cmd))
            out, err, rc = ssh.execute_command(cmd)
            out = out.strip()
            err = err.strip()
            if rc == 0:
                logger.info('output: {}'.format(out))
                return out
            else:
                raise IperfExecutionError(err)

    def _is_process_stopped(self, pid, cmd, ssh):
        start = time.time()
        try:
            while time.time() - start < 10:
                self._pid_exists(pid, ssh)
        except IperfExecutionError:
            # self._pid = None
            sys.exc_clear()
        else:
            self._execute('kill -9 {}'.format(pid), ssh)
            # raise StopProcessError("{} process can not be stopped on iperf"
            #                        " machine".format(cmd))

    def _is_process_started(self, pid, cmd, ssh):
        start = time.time()
        try:
            while time.time() - start < 10:
                self._pid_exists(pid, ssh)
        except IperfExecutionError:
            raise StartProcessError("{} process was not started".format(cmd))

    def _pid_exists(self, pid, ssh):
        self._execute('ps -p {}'.format(pid), ssh)
